TITLES = [("added", "Добавлено:"), ("fixed", "Исправлено:"), ("changed", "Изменено:")]


def release_notes(changes):
    blocks = []
    for kind, title in TITLES:
        items = [text for k, text in changes if k == kind]
        if items:
            blocks.append("\n".join([title] + [f"- {t}" for t in items]))
    return "\n\n".join(blocks) if blocks else "Без изменений"

